#include <algorithm>
#include <cstdint>
#include <iostream>
#include <vector>

using namespace std;

const int MOD = 1000000007;

struct Cell {
    int r;
    int c;
};

static bool rowMajorLess(const Cell& a, const Cell& b) {
    return a.r != b.r ? a.r < b.r : a.c < b.c;
}

static int modPow(long long base, int exponent) {
    long long result = 1;
    while (exponent > 0) {
        if (exponent & 1) result = result * base % MOD;
        base = base * base % MOD;
        exponent >>= 1;
    }
    return static_cast<int>(result);
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    if (!(cin >> n >> m)) return 0;

    vector<Cell> blocked;
    blocked.reserve(static_cast<size_t>(m));
    for (int i = 0; i < m; ++i) {
        Cell cell;
        cin >> cell.r >> cell.c;
        blocked.push_back(cell);
    }

    sort(blocked.begin(), blocked.end(), rowMajorLess);
    blocked.erase(unique(blocked.begin(), blocked.end(), [](const Cell& a, const Cell& b) {
        return a.r == b.r && a.c == b.c;
    }), blocked.end());

    const Cell start{0, 0};
    const Cell finish{n - 1, n - 1};
    if (binary_search(blocked.begin(), blocked.end(), start, rowMajorLess) ||
        binary_search(blocked.begin(), blocked.end(), finish, rowMajorLess)) {
        cout << 0 << '\n';
        return 0;
    }

    const uint64_t obstacleCount = static_cast<uint64_t>(blocked.size());
    const uint64_t pairWork = obstacleCount * (obstacleCount + 1) / 2;
    const uint64_t gridWork = static_cast<uint64_t>(n) * static_cast<uint64_t>(n);

    if (pairWork > gridWork / 8) {
        // Dense fallback: stream row-major obstacles while updating one contiguous DP row.
        vector<int> dp(n, 0);
        size_t nextBlocked = 0;
        for (int r = 0; r < n; ++r) {
            for (int c = 0; c < n; ++c) {
                if (nextBlocked < blocked.size() &&
                    blocked[nextBlocked].r == r && blocked[nextBlocked].c == c) {
                    dp[c] = 0;
                    ++nextBlocked;
                } else if (r == 0) {
                    dp[c] = (c == 0) ? 1 : dp[c - 1];
                } else if (c > 0) {
                    int value = dp[c] + dp[c - 1];
                    if (value >= MOD) value -= MOD;
                    dp[c] = value;
                }
            }
        }
        cout << dp[n - 1] << '\n';
        return 0;
    }

    // Sparse case: count paths to each obstacle by inclusion-exclusion.
    sort(blocked.begin(), blocked.end(), [](const Cell& a, const Cell& b) {
        const int sumA = a.r + a.c;
        const int sumB = b.r + b.c;
        if (sumA != sumB) return sumA < sumB;
        return rowMajorLess(a, b);
    });

    const int maxIndex = 2 * (n - 1);
    vector<int> fact(maxIndex + 1, 1);
    vector<int> invFact(maxIndex + 1, 1);
    for (int i = 1; i <= maxIndex; ++i) {
        fact[i] = static_cast<int>(1LL * fact[i - 1] * i % MOD);
    }
    invFact[maxIndex] = modPow(fact[maxIndex], MOD - 2);
    for (int i = maxIndex; i > 0; --i) {
        invFact[i - 1] = static_cast<int>(1LL * invFact[i] * i % MOD);
    }

    auto choose = [&](int total, int selected) -> int {
        return static_cast<int>(1LL * fact[total] * invFact[selected] % MOD *
                                invFact[total - selected] % MOD);
    };

    vector<int> ways(blocked.size(), 0);
    for (size_t i = 0; i < blocked.size(); ++i) {
        const Cell& cell = blocked[i];
        long long value = choose(cell.r + cell.c, cell.r);
        for (size_t j = 0; j < i; ++j) {
            const Cell& previous = blocked[j];
            if (previous.r <= cell.r && previous.c <= cell.c) {
                const int dr = cell.r - previous.r;
                const int dc = cell.c - previous.c;
                value -= 1LL * ways[j] * choose(dr + dc, dr) % MOD;
                if (value < 0) value += MOD;
            }
        }
        ways[i] = static_cast<int>(value);
    }

    const int target = n - 1;
    long long answer = choose(2 * target, target);
    for (size_t i = 0; i < blocked.size(); ++i) {
        const int dr = target - blocked[i].r;
        const int dc = target - blocked[i].c;
        answer -= 1LL * ways[i] * choose(dr + dc, dr) % MOD;
        if (answer < 0) answer += MOD;
    }

    cout << answer << '\n';
    return 0;
}
